export const FULL_ROAD_EXPANDED_REQUIRED_ROW_IDS_V4 = Object.freeze(EXPANDED_SPECS.map((spec) => spec.id));
export const FULL_ROAD_EXPANDED_REQUIRED_MATERIAL_ROW_IDS_V4 = Object.freeze(EXPANDED_SPECS.filter((spec) => spec.category === "material" || spec.category === "equipment").map((spec) => spec.id));
export const FULL_ROAD_EXPANDED_INFORMATIONAL_COMPONENT_ROW_IDS_V4 = Object.freeze(EXPANDED_SPECS.filter((spec) => spec.informational === true).map((spec) => spec.id));

type Context = {
  area: number;
  length: number;
  kilometre: number;
  asphaltMass: number;
  earthVolume: number;
  cableLength: number;
  poleCount: number;
};

function contextFor(input: { area_m2: number; length_m: number | null; values: ReadonlyMap<string, unknown> }): Context {
  const length = input.length_m && input.length_m > 0 ? input.length_m : Math.sqrt(input.area_m2 * 4);
  const numberValue = (key: string, fallback: number): number => {
    const raw = input.values.get(key);
    const parsed = typeof raw === "number" ? raw : typeof raw === "string" ? Number(raw.replace(/\s+/gu, "").replace(",", ".")) : Number.NaN;
    return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
  };
  return {
    area: input.area_m2,
    length,
    kilometre: length / 1000,
    asphaltMass: input.area_m2 * 0.2 * 2.35 * 1.02,
    earthVolume: input.area_m2 * 0.3,
    cableLength: numberValue("lighting_cable_length_m", length * 2.2),
    poleCount: Math.max(1, Math.ceil(length / numberValue("lighting_pole_spacing_m", 35)) * 2),
  };
}

function baseValue(context: Context, basis: QuantityBasis): number {
  if (basis === "area") return context.area;
  if (basis === "length") return context.length;
  if (basis === "both_sides") return context.length * 2;
  if (basis === "kilometre") return context.kilometre;
  if (basis === "asphalt_mass") return context.asphaltMass;
  if (basis === "earth_volume") return context.earthVolume;
  if (basis === "cable_length") return context.cableLength;
  if (basis === "pole_count") return context.poleCount;
  return 1;
}

function actionFor(category: BoqCategoryV4): string {
  if (category === "material" || category === "equipment") return "поставить";
  if (category === "labor") return "выполнить";
  if (category === "machinery") return "эксплуатировать";
  if (category === "transport") return "доставить";
  if (category === "testing") return "испытать";
  if (category === "documentation") return "оформить";
  return "выполнить";
}

export function buildAsphaltFullRoadExpandedBoqV4(input: {
  area_m2: number;
  length_m: number | null;
  values: ReadonlyMap<string, unknown>;
}): FullRoadInfrastructureLineV4[] {
  const context = contextFor(input);
  const explicitlyDisabled = (key: string): boolean => {
    const value = input.values.get(key);
    return value === false || (typeof value === "string" && /^(?:false|no|нет)$/iu.test(value.trim()));
  };
  const disabledWbs = new Set<FullRoadExpandedWbsCodeV4>([
    ...(explicitlyDisabled("curb_required") ? ["13" as const] : []),
    ...(explicitlyDisabled("drainage_required") || explicitlyDisabled("storm_sewer_required") ? ["15" as const, "16" as const, "17" as const, "18" as const] : []),
    ...(explicitlyDisabled("road_marking_required") ? ["19" as const] : []),
    ...(explicitlyDisabled("traffic_signs_required") ? ["20" as const] : []),
    ...(explicitlyDisabled("guardrail_required") ? ["21" as const] : []),
    ...(explicitlyDisabled("lighting_required") ? ["22" as const, "23" as const, "24" as const] : []),
  ]);
  return EXPANDED_SPECS.filter((spec) => !disabledWbs.has(spec.wbs)).map((spec) => {
    const raw = baseValue(context, spec.basis) * spec.factor;
    const countUnit = ["pcs", "trip", "test", "document", "service"].includes(spec.unit);
    const quantity = countUnit ? Math.max(1, Math.ceil(raw)) : Math.max(0.001, Number(raw.toFixed(6)));
    const inputKey = `${spec.id}_preliminary_quantity`;
    const source = ["19", "20", "21", "25"].includes(spec.wbs)
      ? "eaeu_tr_ts_014_2011"
      : ["22", "23", "24"].includes(spec.wbs)
        ? "eaeu_tr_ts_004_2011"
        : spec.wbs === "28" || spec.wbs === "29"
          ? "kg_mtd_road_quality_control"
          : "kg_krer_2015_collection_27";
    return {
      row_id: spec.id,
      wbs_code: spec.wbs,
      section: FULL_ROAD_EXPANDED_WBS_V4[spec.wbs],
      phase: `full_road_wbs_${spec.wbs}`,
      category: spec.category,
      name_ru: spec.name,
      action: actionFor(spec.category),
      action_object: spec.name.toLocaleLowerCase("ru-RU"),
      specification_ru: `${spec.detail} Количество является видимым редактируемым профессиональным допущением до выпуска проекта.`,
      unit_id: spec.unit,
      formula_id: `${spec.id}_formula_v1`,
      expression: inputKey,
      input_units: { [inputKey]: spec.unit },
      input_values: { [inputKey]: quantity },
      quantity,
      applicability: "scope_profile == NEW_FULL_ROAD_INFRASTRUCTURE",
      inclusion_reason_ru: `${FULL_ROAD_EXPANDED_WBS_V4[spec.wbs]} включён по умолчанию для полного строительства дороги.`,
      exclusion_rule: "Исключить только явным действием пользователя с сохранением причины либо подтверждённым проектным решением.",
      source_ids: [`engineering_assumption:full-road-expanded-boq:v1:${spec.id}`, source],
      price_key: spec.procurement ? `${spec.id}_project_spec` : null,
      procurement: spec.procurement === true,
      cost_ownership_id: `full-road:${spec.wbs}:${spec.id}`,
      informational: spec.informational === true,
      component_type: spec.informational ? "INFORMATIONAL" : undefined,
      specification_status: "PRELIMINARY_ENGINEERING_ASSUMPTION",
    };
  });
}
